ALTER TABLE commerce.products ADD COLUMN description text NOT NULL DEFAULT '', ADD COLUMN media jsonb NOT NULL DEFAULT '[]', ADD COLUMN source_media_id text, ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now(), ADD COLUMN version integer NOT NULL DEFAULT 1;
CREATE UNIQUE INDEX product_instagram_source ON commerce.products(organization_id,source_media_id) WHERE source_media_id IS NOT NULL;
ALTER TABLE commerce.merchants ADD COLUMN bio text NOT NULL DEFAULT '', ADD COLUMN shipping_fee_minor bigint NOT NULL DEFAULT 0 CHECK(shipping_fee_minor>=0), ADD COLUMN shipping_days integer NOT NULL DEFAULT 3 CHECK(shipping_days BETWEEN 1 AND 60), ADD COLUMN return_policy text NOT NULL DEFAULT '', ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
ALTER TABLE commerce.orders ADD COLUMN shipping_address jsonb NOT NULL DEFAULT '{}', ADD COLUMN shipping_fee_minor bigint NOT NULL DEFAULT 0 CHECK(shipping_fee_minor>=0), ADD COLUMN expires_at timestamptz, ADD COLUMN tracking_code text, ADD COLUMN carrier text, ADD COLUMN updated_at timestamptz NOT NULL DEFAULT now();
CREATE TABLE commerce.order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES commerce.orders(id),variant_id uuid NOT NULL REFERENCES commerce.variants(id),title text NOT NULL,sku text NOT NULL,attributes jsonb NOT NULL,quantity integer NOT NULL CHECK(quantity>0),unit_price_minor bigint NOT NULL CHECK(unit_price_minor>0),UNIQUE(order_id,variant_id));
CREATE TABLE commerce.addresses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES commerce.users(id),label text NOT NULL,recipient text NOT NULL,phone text NOT NULL,province text NOT NULL,city text NOT NULL,postal_code text NOT NULL,address text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE commerce.saved_products(user_id uuid NOT NULL REFERENCES commerce.users(id),product_id uuid NOT NULL REFERENCES commerce.products(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,product_id));
CREATE TABLE commerce.followed_merchants(user_id uuid NOT NULL REFERENCES commerce.users(id),merchant_id uuid NOT NULL REFERENCES commerce.merchants(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,merchant_id));
CREATE TABLE commerce.reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES commerce.orders(id),buyer_id uuid NOT NULL REFERENCES commerce.users(id),rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5),body text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(order_id));
CREATE TABLE commerce.support_tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES commerce.users(id),order_id uuid REFERENCES commerce.orders(id),subject text NOT NULL,body text NOT NULL,status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved')),reply text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE commerce.user_notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES commerce.users(id),order_id uuid REFERENCES commerce.orders(id),kind text NOT NULL,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE commerce.analytics_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES commerce.users(id),organization_id uuid REFERENCES commerce.organizations(id),name text NOT NULL,properties jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX analytics_org_time ON commerce.analytics_events(organization_id,created_at);
CREATE TABLE commerce.instagram_launch_tickets(digest text PRIMARY KEY,organization_id uuid NOT NULL REFERENCES commerce.organizations(id),user_id uuid NOT NULL REFERENCES commerce.users(id),session_hash text NOT NULL REFERENCES commerce.sessions(token_hash) ON DELETE CASCADE,expires_at timestamptz NOT NULL);
CREATE INDEX order_expiry ON commerce.orders(expires_at) WHERE status='pending_payment';
INSERT INTO commerce.categories(name,slug) VALUES('پوشاک','clothing'),('خانه و آشپزخانه','home'),('زیبایی','beauty'),('اکسسوری','accessories'),('دیجیتال','electronics') ON CONFLICT(slug) DO NOTHING;
